function getBadgeCounts(state) {
  const activeLeads = (state.leads || []).filter((l) => l.stage_id !== 'deal' && l.stage_id !== 'reject').length;
  const unreadWa = (state.waConversations || []).reduce((sum, c) => sum + (c.unread_count || 0), 0);
  const pendingInvoices = (state.invoices || []).filter((i) => i.status === 'Draft').length;
  return { activeLeads, unreadWa, pendingInvoices };
}

