export function bindSidebarEvents() {
  // Navigation clicks
  document.querySelectorAll('.sidebar-nav-item[data-view]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const view = btn.dataset.view;
      store.setState({ activeView: view });
      // Close mobile sidebar
      const sidebar = document.getElementById('sidebar');
      const overlay = document.getElementById('sidebar-mobile-overlay');
      if (sidebar) sidebar.classList.remove('mobile-open');
      if (overlay) overlay.classList.remove('visible');
    });
  });

  // Theme toggle in sidebar footer
  const themeBtn = document.getElementById('sidebar-theme-toggle');
  if (themeBtn) {
    themeBtn.addEventListener('click', () => store.toggleDarkMode());
  }

  // Mobile overlay click
  const overlay = document.getElementById('sidebar-mobile-overlay');
  if (overlay) {
    overlay.addEventListener('click', () => {
      const sidebar = document.getElementById('sidebar');
      if (sidebar) sidebar.classList.remove('mobile-open');
      overlay.classList.remove('visible');
    });
  }
}

export function mountSidebar(container) {
  container.innerHTML = renderSidebar();
  bindSidebarEvents();

  // Subscribe to store changes for reactive updates
  const unsubscribe = store.subscribe(() => {
    container.innerHTML = renderSidebar();
    bindSidebarEvents();
  });

  return unsubscribe;
}
